template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 30mm;
  height: 20mm;
  padding: 1mm 1.2mm 0.8mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 6.5px;
  font-weight: 700;
  line-height: 1.1;
  max-height: 1.1em;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.price {
  font-size: 10px;
  font-weight: 800;
  margin-top: 0.4mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 6px;
  font-weight: 700;
  margin-left: 0.4mm;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.45mm;
  margin-top: auto;
  width: 100%;
}
.code {
  font-size: 6.5px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.04em;
  text-align: center;
  white-space: nowrap;
}
img.barcode {
  height: 7.5mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
